sql.sql:
SELECT COUNT(DISTINCT race) AS races
FROM results
WHERE session='R' AND Abbreviation='VER' AND season=2024;

SELECT COUNT(*) as pole_cnt FROM results r
 JOIN driver_seasons ds ON r.Abbreviation = ds.driver_code AND ds.season = 2024
 WHERE r.session='Q' AND r.Position=1 AND ds.full_name='Max Verstappen';

